{
  "packet_id": "H6-T02-2",
  "claim_id": "C075",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C075",
    "value": "An explanation's survival of contradiction does not prove that it is the cause.",
    "scope": "A general limit on inference from surviving alternatives, independent of any particular canary outcome.",
    "provenance": {
      "refs": [
        {
          "source_id": "P033",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P033 directly states the claimed limit on causal proof."
    }
  },
  "signal_basis": {
    "component_id": "C075_signal_basis",
    "value": "An explanation survives an evidence-by-hypothesis comparison that assesses consistency, reliability and diagnostic value, tests sensitivity to uncertain evidence, and weakens or eliminates alternatives according to adequately tested contradictions.",
    "scope": "Survival within the evidence and hypotheses examined; omitted causes, shared assumptions and subjective judgments may still leave the ranking wrong.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the comparison procedure, sensitivity checks, bounded elimination rule and remaining sources of error."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C075_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The supported inferential limit does not require an unresolved empirical relation."
    }
  },
  "rationale": "Even when the comparison is executed correctly and an explanation survives, consistency with the examined evidence does not establish causal truth. Other explanations can fit that evidence, including omitted causes. The claim accurately limits what survival licenses.",
  "uncertainty": "No material uncertainty about this general limit; the actual cause remains undetermined by survival alone.",
  "anomalies": []
}
